// sdkDelete deletes the supplied resource in the backend AWS service API
func (rm *resourceManager) sdkDelete(
	ctx context.Context,
	r *resource,
) (latest *resource, err error) {
	rlog := ackrtlog.FromContext(ctx)
	exit := rlog.Trace("rm.sdkDelete")
	defer func() {
		exit(err)
	}()
	if r.ko.Status.Status != nil {
		if !ackutil.InStrings(*r.ko.Status.Status, []string{"READY", "CREATE_FAILED", "UPDATE_FAILED", "DELETE_FAILED"}) {
			return nil, ackrequeue.NeededAfter(
				fmt.Errorf("resource is in %s state, cannot be deleted",
					*r.ko.Status.Status),
				time.Duration(30)*time.Second,
			)
		}
	}

	input, err := rm.newDeleteRequestPayload(r)
	if err != nil {
		return nil, err
	}
	var resp *svcsdk.DeleteHarnessOutput
	_ = resp
	resp, err = rm.sdkapi.DeleteHarness(ctx, input)
	rm.metrics.RecordAPICall("DELETE", "DeleteHarness", err)
	return nil, err
}

// newDeleteRequestPayload returns an SDK-specific struct for the HTTP request
// payload of the Delete API call for the resource
